  // Logika spec var representing port state for outgoing data port
  @spec var station_facts: Docking_Access_Supervisor.StationFacts = $

  def put_station_facts(value : Docking_Access_Supervisor.StationFacts) : Unit = {
    Contract(
      Modifies(station_facts),
      Ensures(
        station_facts == value
      )
    )
    Spec {
      station_facts = value
    }

    Art.putValue(station_facts_Id, Docking_Access_Supervisor.StationFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class StationReportAssessment_Initialization_Api (
